context.snippet:
				}
			}

			kwl = LIST_NEXT(&kwl->list, struct srv_kw_list *, list);
			ctx->obj1 = kwl;
			ctx->obj2 = kwl->kw;
		}
		break;

	case ADD_SRV_MODE_DEF:
		/* Add srv parser must return 1 to prevent I/O handler execution in default mode. */
		ABORT_NOW();
		break;
	}

	return 1;

